#!/bin/sh
# Prints the Homebrew cask for a release, for Casks/emmental.rb in
# Huseyinnurbaki/homebrew-tap. The release workflow runs this after each tag.
#
# Usage: scripts/homebrew-cask.sh 0.2.3 <sha256 of Emmental.zip>
set -eu

VERSION="$1"
SHA256="$2"

cat <<EOF
# Generated by Emmental's release workflow (scripts/homebrew-cask.sh). DO NOT EDIT.
cask "emmental" do
  version "$VERSION"
  sha256 "$SHA256"

  url "https://github.com/Huseyinnurbaki/emmental/releases/download/v#{version}/Emmental.zip"
  name "Emmental"
  desc "Menu bar app for mouse speed, scrolling and Logitech DPI, SmartShift and battery"
  homepage "https://emmental.artichoke.monster/"

  livecheck do
    skip "Auto-generated on release."
  end

  # Install Update in the app's Settings replaces it in place.
  auto_updates true
  depends_on macos: :monterey

  app "Emmental.app"

  # Not notarized yet; clearing the download flag skips the Open Anyway step.
  postflight_steps do
    run "/usr/bin/xattr", args: ["-dr", "com.apple.quarantine", "{{appdir}}/Emmental.app"]
  end

  # The launchctl entry is open at login; removing it also deletes its plist.
  uninstall launchctl: "app.emmental.Emmental",
            quit:      "app.emmental.Emmental"

  zap trash: "~/Library/Preferences/app.emmental.Emmental.plist"

  caveats <<~EOS
    Emmental lives in the menu bar. The Logitech features (DPI, battery,
    SmartShift) ask for Input Monitoring the first time you turn them on.
  EOS
end
EOF
